def norm(cells):
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    r0,c0=min(rs),min(cs)
    return frozenset((r-r0,c-c0) for r,c in sorted(cells))

def rot(cells):  # 90 deg
    return frozenset((c,-r) for r,c in cells)

def dihedral(cells):
    s=frozenset(cells); outs=[]
    for _ in range(4):
        outs.append(norm(s)); s=rot(s)
    s=frozenset((r,-c) for r,c in s)
    for _ in range(4):
        outs.append(norm(s)); s=rot(s)
    return set(outs)

