def comps4(g, bg):
    out = {}
    for c in sorted(set(g.flat)-{bg}):
        lab, n = ndimage.label(g==c)  # default 4-conn
        for i in range(1, n+1):
            cells = {(r,cc) for r,cc in zip(*np.where(lab==i))}
            rs=[r for r,_ in cells]; cs=[c2 for _,c2 in cells]
            out.setdefault(c, []).append(dict(cells=cells, h=max(rs)-min(rs)+1, w=max(cs)-min(cs)+1,
                                              r0=min(rs), c0=min(cs), n=len(cells)))
    return out

