def solve_rule(g, bg):
    objs = [dict(color=k, **o) for k in comps4(g,bg) for o in comps4(g,bg)[k]]
    # rebuild cleanly
    objs = []
    for k in comps4(g,bg):
        for o in comps4(g,bg)[k]:
            d=dict(o); d['color']=k; objs.append(d)
    from collections import Counter
    cnt = Counter(o['color'] for o in objs)
    singles = [c for c,n in cnt.items() if n==1]
    res=[]
    for s in singles:
        giv = [o for o in objs if o['color']==s][0]
        gr = (giv['r0'], giv['r0']+giv['h']-1); gc=(giv['c0'], giv['c0']+giv['w']-1)
        inside = [o for o in objs if o is not giv and gr[0]<=o['r0'] and o['r0']+o['h']-1<=gr[1]
                  and gc[0]<=o['c0'] and o['c0']+o['w']-1<=gc[1]]
        for a in inside:
            for b in objs:
                if b is a or b['color']==s: continue
                if b['n']==a['n'] and norm(b['cells'])==norm(a['cells']):
                    res.append((s, (a['color'],a['r0'],a['c0']), (b['color'],b['r0'],b['c0'])))
    return res

